func threeSum(nums []int) [][]int {
	result := [][]int{}
	mapResults := make(map[[3]int]bool)

	sort.Ints(nums)

	for i := 0; i < len(nums)-2 && nums[i] <= 0; i++ {
		if i > 0 && nums[i-1] == nums[i] {
			continue
		}

		complement := 0 - nums[i]

		for left, right := i+1, len(nums)-1; left < right; {
			if nums[left]+nums[right] == complement {
				mapResults[[3]int{nums[i], nums[left], nums[right]}] = true
				right--
				left++
			} else if nums[left]+nums[right] > complement {
				right--
			} else {
				left++
			}
		}
	}

	for triplet := range mapResults {
		result = append(result, []int{triplet[0], triplet[1], triplet[2]})
	}

	return result
}
